    \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}_{a,r_2}
\le \inf_{v \in {\@fontswitch{\relax}{\mathcal} M}^\alpha_n(I)} E(u-v;a, r_1,r_2), 
\end{equation}
where the square of $E(u-v;a, r_1,r_2)$ is given by
\begin{equation*}
E^2(u-v;a, r_1,r_2) = {\left\vert\kern-0.25ex\left\vert\kern-0.25ex\left\vert u-v 
    \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2_{a,r_2}    + \|r_1^{1/4}(u-v)\|_{L^4(I)}^4    + 5\|r_1^{1/4}u\|_{L^4(I)}^2         \|r_1^{1/4}(u-v)\|_{L^4(I)}^2.    
\end{equation*}

First, we show that for any $v \in {\@fontswitch{\relax}{\mathcal} M}^\alpha_n(I)$, we have
\begin{equation}\@bsphack
