    \right\vert\kern-0.25ex\right\vert\kern-0.25ex\right\vert}^2_{a,r_2} + \dfrac12 \int_0^1 r_1\biggl( v^4 + 4u^3(u-v) - u^4\biggr)\,dx, 
\end{equation}
which, together with the identity 
\begin{equation}\@bsphack
  \protected@write\@auxout{} 
         {\string 
