    v^4 + 4u^3(u-v) - u^4 = (u-v)^2\left[(u+v)^2+2u^2 \right]\ge 0,
\end{equation}
implies the validity of \cref{ineq1}.

To bound $J(v)-J(u)$, first we have
\[
(u+v)^2+2u^2 \leq  2(u-v)^2 + 10 u^2 ,
\]
which, together with \cref{iden} and the Cauchy–Schwarz inequality, implies



\[
\int_0^1 r_1\biggl( v^4 + 4u^3(u-v) - u^4\biggr)\,dx \leq 2\|r_1^{1/4}(u-v)\|_{L^4(I)}^4 + 10 \|r_1^{1/4}u\|_{L^4(I)}^2 \|r_1^{1/4}(u-v)\|_{L^4(I)}^2.
\]
Now, \cref{LeaL} follows from \cref{ineq1} with $v=u_n$, the fact that $J(u_n) \leq J(v)$ for all $v \in {\@fontswitch{\relax}{\mathcal} M}^\alpha_n(I)$, \cref{jv-ju}, and the above inequality. This completes the proof of the lemma.
